fetch("/api/status")
  .then(response => response.json())
  .then(status => { document.querySelector("#status").textContent = `Checkout ${status.version}`; });

const form = document.querySelector("#checkout-form");
const result = document.querySelector("#result");
const payButton = document.querySelector("#pay-button");

function loadCart() {
  const raw = window.localStorage.getItem("cart");
  if (!raw) return { items: [] };
  try {
    return JSON.parse(raw);
  } catch (err) {
    return { items: [] };
  }
}

form.addEventListener("submit", event => {
  event.preventDefault();
  const method = document.querySelector("#method").value;
  payButton.disabled = true;
  result.textContent = "Processing payment...";
  fetch("/api/checkout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ cart: loadCart(), method }),
  })
    .then(response => response.json().then(body => ({ ok: response.ok, body })))
    .then(({ ok, body }) => {
      if (!ok) throw new Error(body.error || "Checkout failed");
      result.textContent = `Payment ${body.status}: ${body.amount_cents} cents via ${body.method}`;
    })
    .catch(err => { result.textContent = `Error: ${err.message}`; })
    .finally(() => { payButton.disabled = false; });
});

fetch("/api/status")
  .then(response => response.json())
  .then(status => { document.querySelector("#status").textContent = `Checkout ${status.version}`; });

const cart = { items: [{ price_cents: 1250, quantity: 2 }] };

document.querySelector("#pay-button").addEventListener("click", () => {
  const method = document.querySelector("#method").value;
  const result = document.querySelector("#result");
  result.textContent = "Processing payment\u2026";
  fetch("/api/checkout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ cart, method })
  })
    .then(response => response.json().then(body => ({ ok: response.ok, body })))
    .then(({ ok, body }) => {
      if (!ok) { throw new Error(body.error || "Checkout failed"); }
      const amount = (body.amount_cents / 100).toFixed(2);
      result.textContent = `Payment ${body.status}: ${amount} via ${body.method}`;
    })
    .catch(error => { result.textContent = `Error: ${error.message}`; });
});

